from pathlib import Path
import re
p=Path('index.html');s=p.read_text(encoding='utf-8')
pattern=r'<div class="(?P<cls>[^"]+)" id="boxfc73aaad-b342-9687-acd3-cfc7cd1cdda5"><div\b[^>]*></div></div>'
markup='''<section class="am-introduction" aria-labelledby="am-introduction-title"><div class="am-intro-shell"><header class="am-intro-header"><div><p class="am-intro-label">MEET ARGONMAX</p><h2 id="am-introduction-title">Gemini Argon.<br><span>Your ideas, made real.</span></h2></div><p class="am-intro-deck">A workspace for the things you want to create — and the business you want to build.</p></header><div class="am-intro-body"><figure class="am-intro-visual"><img src="assets/argon-creative-studio.png" alt="Original creative studio illustration with a website design, coral book, printed artwork and blue ceramic star" loading="lazy"><figcaption><span>ONE IDEA. MANY POSSIBILITIES.</span><span>Websites · Books · Designs</span></figcaption></figure><div class="am-intro-story"><h3>Give your next project<br>a place to start.</h3><p>Tell <strong>Gemini 4.0 Argon</strong> what you have in mind. Use ArgonMAX to research, write, design and build — all in one workspace.</p><p>Make something for your own brand, or package your work into a service for clients.</p><dl class="am-intro-deliverables"><div><dt><span class="am-intro-marker am-marker-blue"></span>Build a business website</dt><dd>Turn a brief into pages, copy and a place to showcase a brand.</dd></div><div><dt><span class="am-intro-marker am-marker-coral"></span>Create your next digital product</dt><dd>Shape your knowledge into an ebook, guide or useful resource.</dd></div><div><dt><span class="am-intro-marker am-marker-yellow"></span>Make content for clients</dt><dd>Create designs and marketing assets you can offer as a service.</dd></div></dl></div></div><footer class="am-intro-foot"><div><strong>Your work. Your name on it.</strong><p>Commercial license included. Create for yourself or for clients.</p></div><span class="am-intro-signature">Powered by<br><b>Gemini 4.0 Argon</b></span></footer></div></section>'''
s,n=re.subn(pattern,lambda m:'<div class="'+m['cls']+' am-intro-host" id="boxfc73aaad-b342-9687-acd3-cfc7cd1cdda5">'+markup+'</div>',s,count=1)
assert n==1
s=s.replace('</head>','<link rel="stylesheet" href="assets/argon-introduction.css"></head>',1)
p.write_text(s,encoding='utf-8')
